/**
 * @description Create a connector with full provider configuration or with a known service connection method.
 */
export type ConnectCreateConnectorRequest = (
	| {
			/**
			 * @description Connector implementation type for full configuration. Known types: api-key, discord, github, linear, linq, microsoft-entra, oauth, photon, salesforce, sendblue, slack, snowflake, snowflake-wif. Optional when service and connectionMethod select the type.
			 * @type string
			 */
			type: string;
	  }
	| {
			/**
			 * @description Service slug or URL for which the connector is used. Required when connectionMethod is set. Service alone does not enable preset configuration.
			 * @type string
			 */
			service: string;
			/**
			 * @description Connection method slug of the service. Use it with service to select preset configuration.
			 * @maxLength 64
			 * @type string
			 */
			connectionMethod: string;
	  }
) & {
	/**
	 * @description Provider configuration for the selected connector type or connection method.
	 */
	data: ConnectConnectorCreateData;
	/**
	 * @description SHA-1 digest of a PNG or JPEG icon that is at least 640 by 640 pixels. This field does not accept a URL or image bytes.
	 *
	 * First compute the digest and upload the raw image with [POST /v2/files](https://vercel.com/docs/rest-api/deployments/upload-deployment-files). Send `Content-Length` and the same 40-character digest in `x-vercel-digest`. Then set `icon` to that digest.
	 *
	 * ```js
	 * import { createHash } from 'node:crypto';
	 * import { readFile } from 'node:fs/promises';
	 *
	 * const VERCEL_TOKEN = process.env.VERCEL_TOKEN;
	 * const connectorId = 'scl_...';
	 * const bytes = await readFile('icon.png');
	 * const digest = createHash('sha1').update(bytes).digest('hex');
	 *
	 * await fetch('https://api.vercel.com/v2/files', {
	 *   method: 'POST',
	 *   headers: {
	 *     Authorization: `Bearer ${VERCEL_TOKEN}`,
	 *     'Content-Type': 'application/octet-stream',
	 *     'Content-Length': String(bytes.length),
	 *     'x-vercel-digest': digest,
	 *   },
	 *   body: bytes,
	 * });
	 *
	 * await fetch(`https://api.vercel.com/v2/connect/connectors/${connectorId}`, {
	 *   method: 'PATCH',
	 *   headers: {
	 *     Authorization: `Bearer ${VERCEL_TOKEN}`,
	 *     'Content-Type': 'application/json',
	 *   },
	 *   body: JSON.stringify({ icon: digest }),
	 * });
	 * ```
	 *
	 * @pattern ^[0-9a-fA-F]{40}$
	 * @type string | undefined
	 */
	icon?: string | undefined;
	/**
	 * @description Branding background color (6-digit hex, for example
	 * @pattern ^#[0-9a-fA-F]{6}$
	 * @type string | undefined
	 */
	backgroundColor?: string | undefined;
	/**
	 * @description Branding accent color (6-digit hex, for example
	 * @pattern ^#[0-9a-fA-F]{6}$
	 * @type string | undefined
	 */
	accentColor?: string | undefined;
	/**
	 * @description Connector implementation type for full configuration. Known types: api-key, discord, github, linear, linq, microsoft-entra, oauth, photon, salesforce, sendblue, slack, snowflake, snowflake-wif. Optional when service and connectionMethod select the type.
	 * @type string | undefined
	 */
	type?: string | undefined;
	/**
	 * @description Service slug or URL for which the connector is used. Required when connectionMethod is set. Service alone does not enable preset configuration.
	 * @type string | undefined
	 */
	service?: string | undefined;
	/**
	 * @description Connection method slug of the service. Use it with service to select preset configuration.
	 * @maxLength 64
	 * @type string | undefined
	 */
	connectionMethod?: string | undefined;
	/**
	 * @description Values for the selected connection method's template fields. Requires connectionMethod.
	 * @type object | undefined
	 */
	params?:
		| {
				[key: string]: string;
		  }
		| undefined;
	/**
	 * @description Which of the service's targets this connector is for. Requires \"connectionMethod\" and must be one that method serves. Optional.
	 * @maxLength 64
	 * @type string | undefined
	 */
	target?: string | undefined;
	/**
	 * @description Optional team-scoped unique identifier for the connector. If omitted or empty, Connect generates a value.
	 * @type string | undefined
	 */
	uid?: string | undefined;
	/**
	 * @description Connector name. The value is trimmed and cannot contain control characters. If omitted or empty, the project name is used. A name or projectId is required. API key connectors require name.
	 * @type string | undefined
	 */
	name?: string | undefined;
	/**
	 * @description Project to connect during creation. If environments is omitted, the connection uses development, preview, and production.
	 * @type string | undefined
	 */
	projectId?: string | undefined;
	/**
	 * @description Environments for the project connection. Requires projectId. Use one or more built-in environment names or stable custom environment IDs that belong to the project. Duplicate values are accepted and removed.
	 * @type array | undefined
	 */
	environments?: string[] | undefined;
	/**
	 * @description Whether the triggers are enabled for this connector.
	 * @type boolean | undefined
	 */
	triggers?: boolean | undefined;
	/**
	 * @description Trigger driver type. Resolved automatically from the known service connection method when not provided. Only set when using the newly decoupled triggers resolution flow.
	 * @type string | undefined
	 */
	triggerType?: string | undefined;
	/**
	 * @description Plaintext verification inputs, validated by the trigger driver and encrypted into stored triggerData. An empty object makes no changes.
	 * @type object | undefined
	 */
	triggerVerificationInput?:
		| {
				[key: string]: unknown;
		  }
		| undefined;
	/**
	 * @description Additional registration inputs, validated by the trigger driver. Requires triggers: true. Shared verification credentials are read from triggerData.
	 * @type object | undefined
	 */
	triggerRegistrationInput?:
		| {
				[key: string]: unknown;
		  }
		| undefined;
	/**
	 * @description Initial trigger destination. Requires triggers to be enabled and a projectId here or at the top level. Connector responses expose the resulting set as triggerDestinations. Replace the complete set with PATCH /v1/connect/connectors/{connector}/trigger-destinations.
	 */
	triggerDestination?:
		| (
				| {
						/**
						 * @description Project that receives triggers. During connector creation, omit it to use the top-level projectId.
						 * @minLength 1
						 * @type string | undefined
						 */
						projectId?: string | undefined;
						/**
						 * @description Route path on the linked project that receives forwarded trigger requests.
						 * @minLength 1
						 * @maxLength 2048
						 * @type string | undefined
						 */
						path?: string | undefined;
				  }
				| {
						/**
						 * @description Project that receives triggers. During connector creation, omit it to use the top-level projectId.
						 * @minLength 1
						 * @type string | undefined
						 */
						projectId?: string | undefined;
						/**
						 * @description Git branch used to select a preview deployment.
						 * @minLength 1
						 * @maxLength 250
						 * @type string
						 */
						branch: string;
						/**
						 * @description Route path on the linked project that receives forwarded trigger requests.
						 * @minLength 1
						 * @maxLength 2048
						 * @type string | undefined
						 */
						path?: string | undefined;
				  }
				| {
						/**
						 * @description Project that receives triggers. During connector creation, omit it to use the top-level projectId.
						 * @minLength 1
						 * @type string | undefined
						 */
						projectId?: string | undefined;
						/**
						 * @description Stable custom environment ID that belongs to the destination project.
						 * @pattern ^env_
						 * @type string
						 */
						customEnvironmentId: string;
						/**
						 * @description Route path on the linked project that receives forwarded trigger requests.
						 * @minLength 1
						 * @maxLength 2048
						 * @type string | undefined
						 */
						path?: string | undefined;
				  }
		  )
		| undefined;
	/**
	 * @description Default trigger events for this connector.
	 * @type array | undefined
	 */
	events?: string[] | undefined;
};

/**
 * @description Existing authorizations no longer cover the connector's configured scopes, so they must be re-authorized.
 * @type object
 */
export type ConnectReconsent = {
	/**
	 * @description The affected authorization scope. user means each affected user must authorize again.
	 * @type string
	 */
	scope: "user";
};

/**
 * @description Provider synchronization errors, when synchronization is required.
 * @type object
 */
export type ConnectServiceSyncError = {
	/**
	 * @description Connector fields that caused the synchronization error.
	 * @type array | undefined
	 */
	fields?: string[] | undefined;
	/**
	 * @description Human-readable provider synchronization error.
	 * @type string
	 */
	message: string;
	/**
	 * @description Provider-specific error details that are safe to expose.
	 * @type object | undefined
	 */
	vendor?:
		| {
				[key: string]: unknown;
		  }
		| undefined;
};

export const connectServiceSyncStatusEnum = {
	done: "done",
	required: "required",
} as const;

export type ConnectServiceSyncStatusEnumKey =
	(typeof connectServiceSyncStatusEnum)[keyof typeof connectServiceSyncStatusEnum];

/**
 * @description Provider-side configuration synchronization result.
 * @type object
 */
export type ConnectServiceSync = {
	/**
	 * @description Provider synchronization errors. Present when serviceSync.status is required.
	 * @type array | undefined
	 */
	errors?: ConnectServiceSyncError[] | undefined;
	/**
	 * @description done means the external service was updated. required means the Vercel update was saved, but provider-side configuration still needs attention.
	 * @type string
	 */
	status: ConnectServiceSyncStatusEnumKey;
};

/**
 * @description Updated connector and any required provider follow-up actions.
 * @type object
 */
export type ConnectConnectorUpdateResult = {
	/**
	 * @description Updated connector.
	 * @type object
	 */
	connector: ConnectConnector;
	/**
	 * @description Present when affected users must authorize the connector's new permissions.
	 * @type object | undefined
	 */
	reconsentNeeded?: ConnectReconsent | undefined;
	/**
	 * @description When true, prompt a team owner or administrator to reinstall the connector before relying on the change.
	 * @type boolean | undefined
	 */
	reinstallNeeded?: (false | true) | undefined;
	/**
	 * @description Result of synchronizing the change with the external service.
	 * @type object | undefined
	 */
	serviceSync?: ConnectServiceSync | undefined;
};

