export const connectUpdateConnectorRequestMcpEventsUiVisibilityEnum = {
	auto: "auto",
	hide: "hide",
	show: "show",
} as const;

export type ConnectUpdateConnectorRequestMcpEventsUiVisibilityEnumKey =
	(typeof connectUpdateConnectorRequestMcpEventsUiVisibilityEnum)[keyof typeof connectUpdateConnectorRequestMcpEventsUiVisibilityEnum];

/**
 * @description Connector fields to update.
 * @type object
 */
export type ConnectUpdateConnectorRequest = {
	/**
	 * @description Whether the triggers are enabled for this connector.
	 * @type boolean | undefined
	 */
	triggers?: boolean | undefined;
	/**
	 * @description Plaintext verification inputs, validated by the trigger driver and encrypted into stored triggerData. An empty object makes no changes.
	 * @type object | undefined
	 */
	triggerVerificationInput?:
		| {
				[key: string]: unknown;
		  }
		| undefined;
	/**
	 * @description Additional registration inputs, validated by the trigger driver. Requires triggers: true. Shared verification credentials are read from triggerData.
	 * @type object | undefined
	 */
	triggerRegistrationInput?:
		| {
				[key: string]: unknown;
		  }
		| undefined;
	/**
	 * @description Default trigger events for this connector.
	 * @type array | undefined
	 */
	events?: string[] | undefined;
	/**
	 * @description MCP Events dashboard visibility. Auto (the default) shows the UI after the first successful delivery. Show and hide persist regardless of future deliveries. This does not enable or disable event delivery.
	 * @type string | undefined
	 */
	mcpEventsUiVisibility?: ConnectUpdateConnectorRequestMcpEventsUiVisibilityEnumKey | undefined;
	/**
	 * @description Provider configuration fields to update.
	 */
	data?: ConnectConnectorUpdateData | undefined;
	/**
	 * @description SHA-1 digest of a PNG or JPEG icon that is at least 640 by 640 pixels. This field does not accept a URL or image bytes.
	 *
	 * First compute the digest and upload the raw image with [POST /v2/files](https://vercel.com/docs/rest-api/deployments/upload-deployment-files). Send `Content-Length` and the same 40-character digest in `x-vercel-digest`. Then set `icon` to that digest.
	 *
	 * ```js
	 * import { createHash } from 'node:crypto';
	 * import { readFile } from 'node:fs/promises';
	 *
	 * const VERCEL_TOKEN = process.env.VERCEL_TOKEN;
	 * const connectorId = 'scl_...';
	 * const bytes = await readFile('icon.png');
	 * const digest = createHash('sha1').update(bytes).digest('hex');
	 *
	 * await fetch('https://api.vercel.com/v2/files', {
	 *   method: 'POST',
	 *   headers: {
	 *     Authorization: `Bearer ${VERCEL_TOKEN}`,
	 *     'Content-Type': 'application/octet-stream',
	 *     'Content-Length': String(bytes.length),
	 *     'x-vercel-digest': digest,
	 *   },
	 *   body: bytes,
	 * });
	 *
	 * await fetch(`https://api.vercel.com/v2/connect/connectors/${connectorId}`, {
	 *   method: 'PATCH',
	 *   headers: {
	 *     Authorization: `Bearer ${VERCEL_TOKEN}`,
	 *     'Content-Type': 'application/json',
	 *   },
	 *   body: JSON.stringify({ icon: digest }),
	 * });
	 * ```
	 *
	 * @pattern ^[0-9a-fA-F]{40}$
	 * @type string | undefined
	 */
	icon?: string | undefined;
	backgroundColor?: string | undefined;
	accentColor?: string | undefined;
	/**
	 * @description Full team-scoped UID, such as `slack/my-bot`. It cannot contain whitespace, `%`, `#`, control characters, or Vercel-owned namespaces. Changing it breaks callers that use the old UID. The stable connector ID does not change.
	 * @type string | undefined
	 */
	uid?: string | undefined;
	/**
	 * @description Display name for the connector. It is trimmed and cannot be empty or contain control characters.
	 * @type string | undefined
	 */
	name?: string | undefined;
};

